WITH kept_keys AS (SELECT id FROM subscriptions EXCEPT ALL SELECT id FROM subscriptions WHERE end_date < '2024-01-01'), kept_rows AS (SELECT s.* FROM subscriptions s INNER JOIN kept_keys k ON s.id = k.id) SELECT id, plan, start_date, end_date, monthly_fee, status, CASE WHEN plan RLIKE '^(premium|enterprise)$' THEN 'GROUP_A' WHEN plan RLIKE '^(basic|standard)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS plan_zone FROM kept_rows;
